// EC49ET exact finite-set group-Steiner DP on a signed native-prefix tree.
// Reads trie generated by EC49ET_optimizer.py; no floating point or solver.
// Input: N K, then N lines: parent baseline 16-bit color mask. Root parent -1.
// Returns exact min number of non-baseline signed-native prefix edges to cover all colors.
#include <algorithm>
#include <cstdint>
#include <cstdio>
#include <iostream>
#include <map>
#include <unordered_map>
#include <vector>
using namespace std;
struct Node {int parent,base,mask;vector<int> kids;};
const int INF=100000000;
int main(){
 ios::sync_with_stdio(false);cin.tie(nullptr);
 int N,K;if(!(cin>>N>>K))return 2;
 if(K>20||N>1000000){cerr<<"bad bounds";return 2;}
 vector<Node> ns(N);
 for(int i=0;i<N;i++){cin>>ns[i].parent>>ns[i].base>>ns[i].mask; if(i&&ns[i].parent>=0&&ns[i].parent<i)ns[ns[i].parent].kids.push_back(i);else if(i){cerr<<"invalid parent";return 2;}}
 vector<unordered_map<int,int>> dps(N);
 size_t largest=0;long long conv=0;
 for(int i=N-1;i>=0;--i){
  unordered_map<int,int> state;state.reserve(16);state[0]=0;
  if(ns[i].mask)state[ns[i].mask]=0;
  for(int c:ns[i].kids){
   auto &child=dps[c];
   unordered_map<int,int> next;
   next.reserve(min(size_t(200000),state.size()*child.size()+1));
   for(auto [m,a]:state)for(auto [n,b]:child){
    ++conv;
    int newmask=m|n;
    int v=a+b+(n&&!ns[c].base);
    auto jt=next.find(newmask);
    if(jt==next.end()||v<jt->second)next[newmask]=v;
   }
   state.swap(next);child.clear();child.rehash(0);
  }
  largest=max(largest,state.size());dps[i]=move(state);
 }
 int full=(1<<K)-1;
 auto it=dps[0].find(full);
 if(it==dps[0].end()){cout<<"INFEASIBLE\n";return 4;}
 cout<<"PASS min_extra="<<it->second<<" total="<<(it->second+28)<<" nodes="<<N<<" colors="<<K<<" largest_states="<<largest<<" convolutions="<<conv<<"\n";
 return 0;
}
